WITH lines AS (SELECT id, customer_id, tag FROM carts LATERAL VIEW OUTER EXPLODE(coupon_codes) e AS tag) SELECT s.id, s.customer_id, s.tag, CASE WHEN tag RLIKE '^(WELCOME5|VIP)$' THEN 'GROUP_A' WHEN tag RLIKE '^(SPRING10|BUNDLE)$' THEN 'OTHER_ZONE' ELSE 'GROUP_B' END AS tag_zone, (SELECT AVG(t2.balance) FROM accounts t2 WHERE t2.customer_id = s.customer_id) AS avg_account_balance FROM lines s ORDER BY tag DESC;
